mapper.select:
SELECT 
FROM bt_data_table a
WHERE a.status_cd = '00A'
  AND a.table_id = #{tableId}
  AND a.tenant_id = #{tenantId}

SELECT a.table_id, a.table_name, a.table_code, a.table_desc, a.data_source_channel, a.catalog_item_id, a.updated_time,
       a.tenant_id, a.updator_id,
       u.real_name AS updatorName, s.data_source_name
FROM bt_data_table a
LEFT JOIN bt_user u ON a.updator_id = u.user_id
LEFT JOIN bt_data_source s ON a.data_source_id = s.data_source_id AND a.tenant_id = s.tenant_id
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{query.tenantId}

  AND (
    a.table_name LIKE #{query.tableName}
    OR
    a.table_code LIKE #{query.tableName}
  )


  AND a.catalog_item_id = #{query.catalogItemId}


  AND a.data_source_channel = #{query.dataSourceChannel}


  AND a.data_source_id = #{query.dataSourceId}

ORDER BY a.updated_time DESC

SELECT a.table_id, a.table_name, a.table_code, a.data_source_id, a.tenant_id
FROM bt_data_table a
WHERE a.status_cd = '00A'

  AND a.tenant_id = #{query.tenantId}


  AND a.data_source_channel = #{query.dataSourceChannel}


  AND a.data_source_id = #{query.dataSourceId}

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_data_table
WHERE status_cd = '00A'
  AND table_code = #{tableCode}
  AND tenant_id = #{tenantId}

SELECT table_icon
FROM bt_data_table
WHERE status_cd = '00A'
  AND table_id = #{tableId}
  AND tenant_id = #{tenantId}

SELECT a.table_id, a.table_name, a.table_code, a.table_desc, a.data_source_id, a.catalog_item_id,
       a.data_source_channel, a.tenant_id
FROM bt_data_table a
WHERE a.status_cd = '00A'
  AND a.table_id = #{tableId}
  AND a.tenant_id = #{tenantId}
